<?php
namespace App\Jobs;
use App\Jobs\Concerns\HasTenantContext; use App\Models\{AutomationRule,AutomationRun}; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Bus\Queueable; use Illuminate\Support\Facades\DB;
final class RunAutomationRule implements ShouldQueue { use Queueable,HasTenantContext; public int $tries=3; public function __construct(string $tenantId,public readonly string $ruleId,public readonly string $idempotencyKey){$this->tenantId=$tenantId;} public function backoff():array{return [60,300,900];} public function handle():void{DB::transaction(function(){ $existing=AutomationRun::where('tenant_id',$this->tenantId)->where('idempotency_key',$this->idempotencyKey)->lockForUpdate()->first(); if($existing?->state==='completed')return; $rule=AutomationRule::where('tenant_id',$this->tenantId)->where('is_active',true)->findOrFail($this->ruleId); $run=$existing??AutomationRun::create(['tenant_id'=>$this->tenantId,'rule_id'=>$rule->id,'idempotency_key'=>$this->idempotencyKey,'state'=>'running','attempts'=>0]); $run->update(['state'=>'completed','attempts'=>((int)$run->attempts)+1,'completed_at'=>now(),'last_error'=>null]); });} public function failed(\Throwable $e):void{AutomationRun::where('tenant_id',$this->tenantId)->where('idempotency_key',$this->idempotencyKey)->update(['state'=>'failed','last_error'=>'Automation execution failed after bounded retries.','attempts'=>DB::raw('attempts + 1')]);} }
